package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Real D-pad, six languages, large text and opaque scene-independent navigation in both apps. */
public final class AndroidNavigationTest extends Instrumentation {
    private Context context;private Activity activity;private String previous,profile,language,phase="setup";
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    Object field(Object target,String name)throws Exception{for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException missing){}throw new NoSuchFieldException(name);}
    void ui(Runnable action){Throwable[] failure={null};runOnMainSync(()->{try{action.run();}catch(Throwable t){failure[0]=t;}});waitForIdleSync();if(failure[0]!=null)throw new AssertionError(failure[0]);}void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
    void boundedImages(View v){if(v instanceof ImageView){Drawable d=((ImageView)v).getDrawable();if(d instanceof BitmapDrawable){Bitmap b=((BitmapDrawable)d).getBitmap();check(b.getWidth()<=192&&b.getHeight()<=192,"Menu retained oversized art: "+b.getWidth()+"x"+b.getHeight()+" in "+v.getContentDescription());}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)boundedImages(((ViewGroup)v).getChildAt(i));}
    void fixedCanvas(Object owner,boolean lite)throws Exception{View canvas=(View)field(owner,lite?"stage":"wallpaper");check(canvas.getWidth()==(lite?3840:1920)&&canvas.getHeight()==(lite?2160:1080)&&canvas.getScaleX()==1f&&canvas.getScaleY()==1f&&canvas.getTranslationX()==0f&&canvas.getTranslationY()==0f,"Full-screen background inherited the content preview transform");if(!lite){View image=(View)field(owner,"backdrop"),surface=(View)field(owner,"surface"),menu=(View)field(owner,"pageBackdrop");check(image.getParent()==canvas&&image.getParent()!=surface,"Home artwork still scales with foreground");check(menu.getWidth()==1920&&menu.getHeight()==1080&&menu.getScaleX()==1f&&menu.getTranslationX()==0,"Menu canvas is cropped");}}
    void opaque(View menu){Bitmap a=Bitmap.createBitmap(menu.getWidth(),menu.getHeight(),Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(menu.getWidth(),menu.getHeight(),Bitmap.Config.ARGB_8888);try{a.eraseColor(Color.RED);b.eraseColor(Color.BLUE);menu.draw(new Canvas(a));menu.draw(new Canvas(b));for(int x=40;x<menu.getWidth()-40;x+=32)for(int y=40;y<menu.getHeight()-40;y+=40)check(a.getPixel(x,y)==b.getPixel(x,y)&&Color.alpha(a.getPixel(x,y))==255,"Menu surface depends on content beneath it");}finally{a.recycle();b.recycle();}}
    void shot(String name)throws Exception{Thread.sleep(180);Bitmap b=getUiAutomation().takeScreenshot();check(b!=null&&b.getWidth()==3840,"Native 4K screenshot required");try(OutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"navigation-"+name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();context=getTargetContext();try{
        try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("getprop ro.kernel.qemu");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd)){check(in.read()=='1',"Owned emulator required");}
        boolean lite=context.getPackageName().endsWith(".lite");previous=VelaWorkspace.active(context);language=L10n.choice();profile=VelaWorkspace.create(context,"Nav · Demo "+SystemClock.elapsedRealtime());VelaWorkspace.select(context,profile);context.getSharedPreferences("personalization",0).edit().putBoolean("initialized",true).putBoolean("complete",true).commit();VelaWorkspace.prefs(context,lite?"lite_updates":"updates").edit().putBoolean("automatic",false).commit();
        int cases=0;for(int textSize:new int[]{0,2})for(String code:new String[]{"es","en","pt","fr","de","it"}){
            phase=code+" / text "+textSize;VelaWorkspace.prefs(context,"visuals").edit().putBoolean("reducedMotion",textSize==2).commit();VelaReading.prefs(context).edit().putInt("text",textSize).commit();L10n.choose(context,code);Ui.init(context);activity=startActivitySync(new Intent().setClassName(context.getPackageName(),"tv.vela.launcher."+(lite?"LiteHomeActivity":"HomeActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object owner=lite?activity:field(activity,"home");View rail=(View)field(owner,lite?"rail":"sidebar"),header=(View)field(owner,lite?"profileAction":"account");List<View> rows=lite?Arrays.asList((View[])field(owner,"navigation")):(List<View>)field(owner,"sideButtons");
            ui(rows.get(0)::requestFocus);Thread.sleep(180);waitForIdleSync();check((Boolean)field(owner,"sidebarOpen")&&rail.getWidth()>300,"Expanded menu did not reveal labels");ui(()->{opaque(rail);boundedImages(rail);});fixedCanvas(owner,lite);View scene=(View)field(owner,lite?"scene":"surface"),heading=(View)field(owner,lite?"heading":"pageTitle");Rect menuBounds=new Rect(),headingBounds=new Rect();ui(()->{rail.getGlobalVisibleRect(menuBounds);heading.getGlobalVisibleRect(headingBounds);});check(headingBounds.left>menuBounds.right,"Expanded navigation cuts the page heading");check(Math.abs(scene.getScaleX()-.84f)<.001f&&Math.abs(scene.getScaleY()-.84f)<.001f,"Content did not become a complete inactive preview");check(Math.abs(scene.getX()+scene.getWidth()*scene.getScaleX()-1920f)<1f,"Preview moved the right screen edge");
            for(View row:rows)if(row.getVisibility()==View.VISIBLE)check(row.getLeft()>=0&&row.getRight()<=rail.getWidth(),"A navigation hit area extends outside the panel");check(header.getRight()<=rail.getWidth(),"Profile hit area extends outside the panel");
            List<TextView> labels=lite?Arrays.asList((TextView[])field(owner,"navigationLabels")):(List<TextView>)field(owner,"sideLabels");for(TextView label:labels)if(label.getParent() instanceof View){check(label.getAlpha()>.98f&&label.getLayout()!=null&&label.getLayout().getLineCount()==1,"Expanded label is hidden or wraps");check(label.getPaint().measureText(label.getText().toString())<=label.getWidth()-label.getPaddingLeft()-label.getPaddingRight(),"A primary label is clipped in "+phase+": "+label.getText());}
            key(KeyEvent.KEYCODE_DPAD_UP);check(header.hasFocus(),"Up did not reach the profile");key(KeyEvent.KEYCODE_DPAD_DOWN);check(rows.get(0).hasFocus(),"Down did not return to the first section");if(textSize==0&&code.equals("es"))shot("expanded");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(!(Boolean)field(owner,"sidebarOpen")&&!rail.hasFocus(),"Right did not return to content");Thread.sleep(150);check(scene.getScaleX()==1f&&scene.getScaleY()==1f&&scene.getTranslationX()==0f,"Returning to content kept a partial preview transform");ui(()->boundedImages(rail));if(textSize==0&&code.equals("es"))shot("collapsed");View origin=activity.getCurrentFocus();ui(rows.get(0)::requestFocus);key(KeyEvent.KEYCODE_BACK);Thread.sleep(150);check(!(Boolean)field(owner,"sidebarOpen")&&activity.getCurrentFocus()==origin&&scene.getScaleX()==1f&&scene.getTranslationX()==0f,"Back did not restore the original content focus and geometry");ui(activity::finish);activity=null;cases++;
        }
        result.putInt("language_and_text_cases",cases);result.putString("result","PASS twelve language/text combinations including reduced motion, complete content preview and exact size restoration, actual profile/section/content D-pad and Back return, full label and hit-area bounds, opaque vector navigation independent of underlay and no scene-sized menu bitmaps. Native 4K captures; isolated local profile, no physical television.");
    }catch(Throwable e){result.putString("error",phase+"\n"+android.util.Log.getStackTraceString(e));}finally{try{if(activity!=null)ui(activity::finish);if(profile!=null){VelaWorkspace.select(context,previous);VelaWorkspace.delete(context,profile);}if(language!=null)L10n.choose(context,language);}catch(Exception ignored){}}finish(result.containsKey("error")?1:-1,result);}
}
